import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
}

interface QuickOption {
  label: string;
  getDate: () => Date;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function daysBeforeToday(days: number): Date {
  const result = startOfDay(new Date());
  result.setDate(result.getDate() - days);
  return result;
}

function isSameDay(a: Date | null | undefined, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

const quickOptions: QuickOption[] = [
  { label: 'Сегодня', getDate: () => daysBeforeToday(0) },
  { label: 'Вчера', getDate: () => daysBeforeToday(1) },
  { label: 'Неделя назад', getDate: () => daysBeforeToday(7) },
];

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState<Date | null>(defaultValue);
  const isControlled = value !== undefined;
  const selectedDate = isControlled ? value : uncontrolledValue;

  const emitChange = (next: Date | null) => {
    if (!isControlled) {
      setUncontrolledValue(next);
    }
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px' }}>
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          return (
            <JxChip
              key={option.label}
              active={isSameDay(selectedDate, optionDate)}
              onClick={() => emitChange(optionDate)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={emitChange} />
    </div>
  );
}

